": "9a31031b-6dae-446e-b4c5-621c08f8aece", "type": "concept", "title": "Skeletons"}, {"id": "40278616-bc6d-400b-93eb-cb05750b3f8a", "type": "concept", "title": "Stroke modulation"}, {"id": "f9370e99-87f5-4dea-a184-fa49fd2c6df2", "type": "concept", "title": "Counters"}, {"id": "32a35fa4-f833-4468-8127-895a41162439", "type": "concept", "title": "Spacing strings"}], "description": "Gist: Custom type depends on consistent proportions, curves, spacing, and optical correction."}, {"id": "d6816e28-1041-474b-928f-956b758bf7c1", "type": "subtopic", "title": "Applied custom type", "children": [{"id": "24278ff9-9941-4d64-beeb-4d24e6c9eca0", "type": "concept", "title": "Wordmarks"}, {"id": "52a44240-39c8-4ffe-9037-b268e3d38fb1", "type": "concept", "title": "Event titles"}, {"id": "c0c572f8-c598-4973-aaea-32c8189938b4", "type": "concept", "title": "Packaging"}, {"id": "9d9a2fc0-7606-4cd8-8b7a-e6262d4d2bd7", "type": "concept", "title": "Editorial openers"}], "description": "Gist: Custom letterforms should solve a real communication or identity problem."}]}, {"id": "27765d5e-f904-4ec5-bd84-14aedf76c1d2", "type": "topic", "title": "Type for Screen and Interaction", "description": "Design typography for responsive layouts, products, interfaces, performance constraints, and real users.", "children": [{"id": "a94a6cac-ef81-4885-85ed-f959e84596be", "type": "subtopic", "title": "Interface typography", "children": [{"id": "fad009b1-23a5-4b3f-a127-181ae03ab8c1", "type": "concept", "title": "Labels"}, {"id": "0f694bbd-9338-4015-b886-cd9e5c8fcd94", "type": "concept", "title": "Buttons"}, {"id": "a0dedca1-ff5a-40b4-b84a-743795d8116c", "type": "concept", "title": "Forms"}, {"id": "eefeaada-03b3-4efc-9713-da909853358c", "type": "concept", "title": "Error states and microcopy"}], "description": "Gist: Interface type must support tasks, feedback, navigation, and comprehension."}, {"id": "8af0b06e-204d-4892-b38a-0184fe0d477e", "type": "subtopic", "title": "Responsive reading", "children": [{"id": "add8f0bd-4a72-4f03-b844-a3a464b0923b", "type": "concept", "title": "Breakpoints"}, {"id": "41f0f272-4bb8-468f-9baa-e0f6eaea6304", "type": "concept", "title": "Fluid type scales"}, {"id": "d427e44d-91a5-4c38-b177-e3c6b0f534c5", "type": "concept", "title": "Line length"}, {"id": "53b696f9-f31f-4faf-87c3-506a703c0007", "type": "concept", "title": "Device testing"}], "description": "Gist: Screen typography changes with viewport, input method, and user settings."}, {"id": "c8131ba9-c1c2-47b3-9227-bd18ea63c8be", "type": "subtopic", "title": "Performance and implementation", "children": [{"id": "3dff9753-e7af-4173-93ab-c87181def8b7", "type": "concept", "title": "Webfont loading"}, {"id": "2feeb72d-82b3-4157-9e31-b940e5d2b218", "type": "concept", "title": "Fallback stacks"}, {"id": "8348488d-b917-4e71-acb2-13b6b2fe93e3", "type": "concept", "title": "Font subsetting"}, {"id": "12c21f41-87af-48c8-a54f-8a4a02d1658c", "type": "concept", "title": "Design handoff"}], "description": "Gist: Digital type choices affect loading, rendering, privacy, and maintainability."}]}, {"id": "c003b185-271c-4d77-9087-dcdd08cd93d9", "type": "topic", "title": "Variable Fonts and Responsive Type Systems", "description": "Use modern font technology to create flexible typographic systems across sizes, devices, and contexts.", "children": [{"id": "a89b87ba-c371-448a-af74-91b7a7724fef", "type": "subtopic", "title": "Variable font axes", "children": [{"id": "e0105a40-248a-4459-bd9a-53e5b91fed6d", "type": "concept", "title": "Weight"}, {"id": "555ebdf7-c256-45d7-a587-7fb978d7d498", "type": "concept", "title": "Width"}, {"id": "4660c118-e817-4bd9-ae94-d62db152a9c9", "type": "concept", "title": "Optical size"}, {"id": "0b5ebd3d-9e43-4251-a7c2-c7d979863787", "type": "concept", "title": "Slant and custom axes"}], "description": "Gist: Variable fonts allow continuous adjustment rather than fixed style jumps."}, {"id": "0d5a1e45-4fb2-4326-b566-c01650f43bcf", "type": "subtopic", "title": "Responsive behavior"