update public.learning_paths
set
  title = 'Typography II',
  goal = 'Typography II',
  summary = 'Typography II uses systematic structures for complex content across pages, screens, campaigns, and identities, including multi-level hierarchy, type palettes, microtypography, display and expressive type, and long-form editorial reading. Students also study motion, custom lettering, screen interaction, variable fonts, multilingual and inclusive type, brand voice, information design, production, licensing, ethics, research, and critique, then synthesize them in an advanced typographic project.',
